for gid,briefs in cases.items():
 g=goals[gid];eid='bounded-nonmolecular-meiotic-causal-explanation'
 cases_out=[dict(id=i,taskDemandDe=td,taskDemandEn=te,expectedPerformanceDe=pd,expectedPerformanceEn=pe,understandingFocusDe='Den ausgewiesenen Mechanismus selbst kausal auf frisches vorgegebenes Material erklären; korrekte Modelle und Keimzellensätze liegen vor, eine Lösungserklärung nicht.',understandingFocusEn='Independently explain the specified mechanism causally using fresh supplied material; correct models and gamete sets are supplied, an explanatory solution is not.') for i,td,te,pd,pe in briefs]
 profile=dict(archetype='modeling',expectations=[dict(id=eid,essentialUnderstandingDe=g['description']+' Die Erklärung bleibt am vorgegebenen nichtmolekularen Modell und korrekt gelieferten Keimzellensätzen; Legenden sind Hilfen, keine selbstständige Lösung.',essentialUnderstandingEn=g['descriptionEn']+' Explanation stays within supplied non-molecular models and correctly supplied gamete sets; legends are aids, not independent learner solutions.',observablePerformanceDe=' '.join(v['expectedPerformanceDe'] for v in cases_out),observablePerformanceEn=' '.join(v['expectedPerformanceEn'] for v in cases_out))],coverageExpectations=dict(requiredExpectationIds=[eid],alternativeExpectationGroups=[],minimumIndependentDemonstrations=2,freshVariationRequired=True,independentTransferRequired=True),variationAxes=[dict(id='fresh-given-model',textDe='Andere Herkunftsfarben, Paarzahl oder Abschnittsposition im vorgegebenen korrekten Modell; identische Kausalleistung bleibt.',textEn='Vary parental-origin colors, number of pairs or corresponding region in the correct supplied model; retain the same causal performance.'),dict(id='bounded-contrast',textDe='Passenden Gegenmechanismus begründet abgrenzen, ohne eine weitere molekulare Routine hinzuzufügen.',textEn='Justify distinction from a relevant other mechanism without adding a molecular routine.')],applicationCaseBriefs=cases_out)
 rows.append(dict(goalId=gid,reason='New inactive bilingual assessment specification for the missing current prospective profile; frozen source/operator/description and actual unchanged PNG scopes respected. Independent current P/D2 pending, no observed learner data.',evidenceLevel='E1',maximumClaimScope='G1',dissent=['Visualization alone is not a complete supplied chromosome/gamete assessment model.','No observed learner performance, operative approval or human approval.'],profile=profile))
out=dict(schemaVersion=1,authoringContract='positive-understanding-evidence-candidates-v1',reviewId='biologie-ni-five-predecessor-native-author-20261005-v2',reviewedAt=datetime.now(timezone.utc).isoformat(),reviewer='Codex inactive native author; three exact prior assessment payloads, two new bounded specifications; independent current review pending',goals=rows)
write('positive-evidence.five-predecessor.candidates.json',out);cfg=read(own/'positive.thirteen.native-author.config.json');cfg.update(reviewId=out['reviewId'],reviewPath=rel+'/positive.five-predecessor.native-author.review.jsonl',scope=dict(label='Five inactive NI predecessor profiles:3 exact payload carry-forward +2 new bounded author profiles',goalIds=[r['goalId'] for r in rows]));write('positive.five-predecessor.native-author.config.json',cfg)
